package com.vandorlabs.gear;

import com.vandorlabs.coupler.*;
import com.vandorlabs.vehicle.*;
import java.lang.reflect.*;
import java.util.*;
import net.minecraft.init.Blocks;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.math.*;
import net.minecraft.world.World;

/** Identity metadata checked against the unchanged released cell collision emission order. */
public final class ArmCollisionIdentityChecks {
    private static int checks;private static volatile VehicleStructure.Cell sink;
    private static void need(boolean v,String why){checks++;if(!v)throw new AssertionError("Arm collision identity: "+why);}
    public static void main(String[] args)throws Exception{
        net.minecraft.init.Bootstrap.register();net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(TileCoupler.class,new ResourceLocation("vandorlabs:square_coupler"));BlockCoupler block=new BlockCoupler();net.minecraftforge.fml.common.registry.ForgeRegistries.BLOCKS.register(block);
        Constructor<?> worldCtor=Class.forName("com.vandorlabs.client.NonRenderingChecks$MemoryWorld").getDeclaredConstructor(boolean.class);worldCtor.setAccessible(true);World world=(World)worldCtor.newInstance(false);
        GearTileEntity arm=new GearTileEntity();arm.setWorld(world);arm.setPos(new BlockPos(8,16,8));List<VehicleStructure.Cell> cells=new ArrayList<>();NBTTagCompound data=new NBTTagCompound();data.setString("id","vandorlabs:square_coupler");data.setString("FutureField","verbatim");NBTTagCompound caps=new NBTTagCompound();caps.setByteArray("OpaqueCapability",new byte[32768]);data.setTag("ForgeCaps",caps);
        for(int i=0;i<7;i++)cells.add(new VehicleStructure.Cell(new BlockPos(i,0,0),i==3?block.getDefaultState().withProperty(BlockCoupler.LOCKED,true):i==1||i==5?Blocks.STONE.getDefaultState():Blocks.AIR.getDefaultState(),i==3?data:null));
        Constructor<ArmPayload> ctor=ArmPayload.class.getDeclaredConstructor(VehicleStructure.class,BlockPos.class,boolean.class,BlockPos.class);ctor.setAccessible(true);ArmPayload payload=ctor.newInstance(VehicleStructure.display(cells),BlockPos.ORIGIN,false,BlockPos.ORIGIN);NBTTagCompound before=payload.write();VehicleWorld local=payload.view(arm);List<AxisAlignedBB> old=new ArrayList<>();List<Integer> owners=new ArrayList<>();for(int c=0;c<cells.size();c++){int start=old.size();VehicleStructure.Cell cell=cells.get(c);cell.state.addCollisionBoxToList(local,cell.pos,new AxisAlignedBB(cell.pos).grow(2),old,null,false);for(int i=start;i<old.size();i++)owners.add(c);}
        need(payload.collisionBoxCount(arm)==old.size()&&old.size()>3,"actual released cells emit boxes with empty-cell boundaries");for(int i=0;i<old.size();i++){VehicleStructure.Cell owner=payload.collisionCell(arm,i);need(payload.collisionCellIndex(arm,i)==owners.get(i),"ordered index matches independent source emitter");need(owner==payload.blocks.cells.get(owners.get(i)),"source box index retains exact original cell");need((owner.state.getBlock() instanceof BlockCoupler)==(owners.get(i)==3),"only actual Coupler components receive a head identity");}
        Field ends=ArmPayload.class.getDeclaredField("collisionCellEnds");ends.setAccessible(true);need(((int[])ends.get(payload)).length==cells.size(),"metadata costs one integer per cell, not per component");need(payload.write().equals(before),"cache construction never rewrites original opaque snapshot");
        for(int invalid:new int[]{-1,old.size()}){boolean refused=false;try{payload.collisionCell(arm,invalid);}catch(IndexOutOfBoundsException expected){refused=true;}need(refused,"invalid box index refuses");}ArmPayload nativeOwner=ctor.newInstance(payload.blocks,BlockPos.ORIGIN,true,BlockPos.ORIGIN);boolean refused=false;try{nativeOwner.collisionCell(arm,0);}catch(IllegalArgumentException expected){refused=true;}need(refused,"native endpoint geometry cannot claim captured box identity");
        java.lang.management.ThreadMXBean base=java.lang.management.ManagementFactory.getThreadMXBean();if(base instanceof com.sun.management.ThreadMXBean){com.sun.management.ThreadMXBean bean=(com.sun.management.ThreadMXBean)base;if(bean.isThreadAllocatedMemorySupported()){bean.setThreadAllocatedMemoryEnabled(true);for(int i=0;i<20000;i++)sink=payload.collisionCell(arm,i%old.size());long id=Thread.currentThread().getId(),start=bean.getThreadAllocatedBytes(id);for(int i=0;i<10000;i++)sink=payload.collisionCell(arm,i%old.size());long bytes=bean.getThreadAllocatedBytes(id)-start;need(bytes==0,"warmed index metadata lookup allocation="+bytes);System.out.println("Arm collision identity allocation PASS queries=10000 bytes="+bytes+" metadataBytes="+(4*cells.size()));}}
        NBTTagCompound edit=data.copy();java.util.UUID lifetime=java.util.UUID.randomUUID();edit.setUniqueId("CouplerControlIdentity",lifetime);edit.setBoolean("CouplerInverted",true);edit.setBoolean("CouplerArticulation",true);com.vandorlabs.redstone.ChannelData.write(edit,com.vandorlabs.redstone.ChannelList.of(27));ArmPayload edited=payload.withCouplerData(cells.get(3).pos,edit);need(payload.write().equals(before),"typed control edit never mutates original owner");need(edited.blocks.at(cells.get(3).pos).tileData().equals(edit),"known edit retains exact opaque original and lifetime");need(edited.capturedCopy().blocks.at(cells.get(3).pos).tileData().getUniqueId("CouplerControlIdentity").equals(lifetime),"capture clone retains lifetime");
        for(int fault=0;fault<5;fault++){NBTTagCompound invalid=edit.copy();if(fault==0)invalid.setString("FutureField","changed");if(fault==1)invalid.getCompoundTag("ForgeCaps").setBoolean("ForeignEdit",true);if(fault==2)invalid.setUniqueId("CouplerControlIdentity",java.util.UUID.randomUUID());if(fault==3)invalid.removeTag("CouplerControlIdentityLeast");if(fault==4)invalid.setString("id","minecraft:sign");boolean rejected=false;try{edited.withCouplerData(cells.get(3).pos,invalid);}catch(IllegalArgumentException expected){rejected=true;}need(rejected,"opaque/type/lifetime mutation refuses fault="+fault);need(edited.blocks.at(cells.get(3).pos).tileData().equals(edit),"refusal retains exact last valid owner");}
        TileCoupler header=new TileCoupler();header.readFromNBT(edit);need(header.writeToNBT(new NBTTagCompound()).getUniqueId("CouplerControlIdentity").equals(lifetime),"materialized tile save retains captured lifetime");NBTTagCompound malformed=edit.copy();malformed.setString("CouplerControlIdentityMost","wrong type");boolean rejected=false;try{new TileCoupler().readFromNBT(malformed);}catch(IllegalArgumentException expected){rejected=true;}need(rejected,"malformed existing lifetime refuses rather than generates replacement");
        NBTTagCompound releaseData=edit.copy();releaseData.setBoolean("CouplerRequested",true);ArmPayload released=edited.releaseCoupler(cells.get(3).pos,true,releaseData);NBTTagCompound releasedData=released.blocks.at(cells.get(3).pos).tileData();need(released.blocks.at(cells.get(3).pos).state.getValue(BlockCoupler.LOCKED)&&releasedData.getBoolean("CouplerRequested"),"unclicked requested partner remains latched after detached release preparation");need(releasedData.getBoolean("VehicleArmCouplerReleased")&&releasedData.getCompoundTag("ForgeCaps").equals(edit.getCompoundTag("ForgeCaps")),"explicit detached-release proof preserves opaque capabilities");need(edited.blocks.at(cells.get(3).pos).tileData().equals(edit),"release preparation leaves live original unchanged");ArmPayload unlocked=edited.releaseCoupler(cells.get(3).pos,false,edit);need(!unlocked.blocks.at(cells.get(3).pos).state.getValue(BlockCoupler.LOCKED),"selected release changes latch only");TileCoupler releasedTile=new TileCoupler();releasedTile.readFromNBT(releasedData);need(releasedTile.writeToNBT(new NBTTagCompound()).getBoolean("VehicleArmCouplerReleased"),"native materialization retains explicit release proof");boolean nativeReleaseRefused=false;try{nativeOwner.releaseCoupler(cells.get(3).pos,false,data);}catch(IllegalArgumentException expected){nativeReleaseRefused=true;}need(nativeReleaseRefused,"native endpoint cannot use captured release patch");
        System.out.println("Arm collision identity PASS checks="+checks+" Source cell emissions="+old.size()+" empty boundaries/exact order/opaque snapshot/native ownership/index guards; active articulation tagging separate");
    }
}
